<?php require __DIR__.'/../config.php';require __DIR__.'/../functions.php';requireAdmin();$status=$_GET['status']??'';$where='';$params=[];if(in_array($status,['confirmed','cancelled','completed'],true)){$where='WHERE b.status=?';$params[]=$status;}$q=db()->prepare("SELECT b.*,c.name car_name FROM bookings b JOIN cars c ON c.id=b.car_id $where ORDER BY b.created_at DESC");$q->execute($params);$rows=$q->fetchAll();$f=getFlash();adminTop('Booking Dashboard','bookings');if($f):?><div class="flash <?=$f['type']?>"><?=e($f['message'])?></div><?php endif;?><div class="tabs"><a class="tab" href="bookings.php">All</a><a class="tab" href="?status=confirmed">Confirmed</a><a class="tab" href="?status=completed">Completed</a><a class="tab" href="?status=cancelled">Cancelled</a></div><div class="table-wrap"><table><thead><tr><th>Code</th><th>Customer</th><th>Vehicle</th><th>Route</th><th>Dates</th><th>KM</th><th>Total</th><th>Status</th><th>Change</th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td><b><?=e($b['booking_code'])?></b><small><?=e($b['created_at'])?></small></td><td><?=e($b['customer_name'])?><small><?=e($b['customer_phone'])?> · <?=e($b['customer_email'])?></small></td><td><?=e($b['car_name'])?></td><td><?=e($b['from_city'])?> → <?=e($b['to_city'])?></td><td><?=e($b['pickup_date'])?> → <?=e($b['return_date'])?></td><td><?=e($b['total_km'])?></td><td><?=money((float)$b['total_amount'])?></td><td><span class="status <?=$b['status']?>"><?=e($b['status'])?></span></td><td><form method="post" action="booking_status.php" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$b['id']?>"><select name="status"><option value="confirmed">Confirmed</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><button class="btn mini ghost">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php adminBottom(); ?>